Definition nc_val (minval maxval : Z) (j : Z) : Z := minval + Z.quot (j * (maxval - minval)) 9.
Definition nc_words (minval maxval : Z) (n : nat) : list word := map (fun j => Z_to_bv 64 (nc_val minval maxval (Z.of_nat j))) (seq 0 n).
