Lemma addguard : forall mn q, 0 <= mn <= 255 -> -255 <= q <= 255 ->
  Z_to_bv 64 (bv_swrap 32 (mn + q mod 18446744073709551616)) = Z_to_bv 64 (mn + q) /\
